class ScribButton extends StatelessWidget {
  const ScribButton({
    super.key,
    required this.label,
    this.variant = ScribButtonVariant.primary,
    this.icon = ScribIcon.auto,
    this.disabled = false,
    this.circle = false,
    this.onPressed,
  });

  final String label;
  final ScribButtonVariant variant;
  final ScribIcon icon;
  final bool disabled;
  final bool circle;
  final VoidCallback? onPressed;

  @override
  Widget build(BuildContext context) {
    if (circle) {
      return base.ScribButton(
        label: label,
        variant: variant,
        icon: icon,
        disabled: disabled,
        circle: true,
        onPressed: onPressed,
      );
    }
    final iconData = base.scribResolveIcon(icon, label);
    return ds.Button(
      variant: switch (variant) {
        ScribButtonVariant.primary => ds.ButtonVariant.regular,
        ScribButtonVariant.accent => ds.ButtonVariant.regular,
        ScribButtonVariant.secondary => ds.ButtonVariant.secondary,
        ScribButtonVariant.outline => ds.ButtonVariant.outline,
        ScribButtonVariant.ghost => ds.ButtonVariant.ghost,
        ScribButtonVariant.link => ds.ButtonVariant.link,
        ScribButtonVariant.destructive => ds.ButtonVariant.destructive,
      },
      size: ds.ButtonSize.regular,
      icon: iconData == null ? null : Icon(iconData),
      onPressed: disabled ? null : (onPressed ?? () {}),
      child: Text(label),
    );
  }
}

class ScribBadge extends StatelessWidget {
  const ScribBadge(this.label, {super.key, this.variant = ScribBadgeVariant.neutral});
  final String label;
  final ScribBadgeVariant variant;

  @override
  Widget build(BuildContext context) {
    final t = context.scribTokens;
    final Color? dot = switch (variant) {
      ScribBadgeVariant.success => t.success,
      ScribBadgeVariant.warning => t.warning,
      _ => null,
    };
    return ds.Badge(
      variant: switch (variant) {
        ScribBadgeVariant.neutral => ds.BadgeVariant.secondary,
        ScribBadgeVariant.primary => ds.BadgeVariant.regular,
        ScribBadgeVariant.destructive => ds.BadgeVariant.destructive,
        ScribBadgeVariant.success => ds.BadgeVariant.outline,
        ScribBadgeVariant.warning => ds.BadgeVariant.outline,
      },
      icon: dot == null ? null : Icon(Icons.circle, color: dot),
      child: Text(label),
    );
  }
}

